#!/usr/bin/env python3
"""Regenerate src/util-scan/gui-page.h from web/gui.html."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
src = ROOT / "web" / "gui.html"
dst = ROOT / "src" / "util-scan" / "gui-page.h"
data = src.read_bytes()
lines = [
    "/* Generated by tools/build_gui_page.py from web/gui.html. Do not edit. */",
    "#ifndef XTATE_GUI_PAGE_H",
    "#define XTATE_GUI_PAGE_H",
    "#include <stddef.h>",
    "static const unsigned char GUI_PAGE[] = {",
]
for i in range(0, len(data), 16):
    chunk = data[i:i + 16]
    lines.append("    " + ", ".join(f"0x{b:02x}" for b in chunk) + ",")
lines.append("    0x00,")
lines.extend([
    "};",
    f"static const size_t GUI_PAGE_LEN = {len(data)};",
    "#endif",
    "",
])
dst.write_text("\n".join(lines), encoding="ascii")
print(f"wrote {dst} ({len(data)} bytes)")
